'use strict';
window.createPhoenixSearch=function({tasks,state,engine,navigate}){
 const model=window.PhoenixSearchModel,context={tasks,state,engine},historyKey='phoenix.search.history.v1';
 const referenceIds=['home','regions','whiteorchard-console','whiteorchard-tree','whiteorchard-map','field-reference','economy','economy-merchants','character','character-gear','gear-diagram-regions','gear-diagrams',...(window.PHOENIX_EXPLORATION?.categories||[]).map(c=>'exploration-'+c.id)];
 const references=referenceIds.map(id=>{const view=document.getElementById(id),heading=view?.querySelector('h1');return heading?{id:'reference:'+id,title:heading.textContent,href:'#'+id,region:id.startsWith('whiteorchard')||id==='gear-diagrams'||id.startsWith('exploration-')?'White Orchard':'Guide-wide',keywords:view.querySelector('.lead,.main-console-intro')?.textContent||''}:null;}).filter(Boolean);
 const index=model.buildIndex({tasks,pins:window.PHOENIX_MAP.markers,references,velenCards:window.PhoenixVelenQuestCards,velenQuests:window.PHOENIX_VELEN?.quests}).filter(row=>row.region==='Velen'||document.getElementById(row.href.slice(1).split('/')[0]));
 const byId=new Map(index.map(row=>[row.id,row]));let recents;try{recents=model.readHistory(localStorage.getItem(historyKey),index);}catch{recents={queries:[],entries:[]};}
 const make=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;};
 const dialog=make('dialog',null,'guide-search-dialog'),paper=make('article',null,'guide-search-paper'),header=make('header'),heading=make('h2','Search the guide'),closeButton=make('button','Close ×');heading.id='guide-search-title';closeButton.type='button';closeButton.setAttribute('aria-label','Close Search');header.append(heading,closeButton);dialog.setAttribute('aria-labelledby',heading.id);
 const form=make('form',null,'guide-search-form'),input=make('input'),submit=make('button','Search');input.type='search';input.maxLength=160;input.placeholder='Quest, activity, diagram or reference…';input.setAttribute('aria-label','Search the guide');input.autocomplete='off';submit.type='submit';form.append(input,submit);
 const filters=make('details',null,'guide-search-filters');filters.append(make('summary','Filters'));const filterRow=make('div',null,'guide-search-filter-row');filters.append(filterRow);
 function select(label,choices){const wrap=make('label',label),control=make('select');control.setAttribute('aria-label',label);choices.forEach(([value,title])=>{const option=make('option',title);option.value=value;control.append(option);});wrap.append(control);filterRow.append(wrap);return control;}
 const region=select('Region',[['all','All regions'],['White Orchard','White Orchard'],['Velen','Velen'],['Guide-wide','Guide-wide reference']]);
 const type=select('Content type',[['all','All content'],['quest','Quests and steps'],['activity','Activities'],['diagram','Diagrams'],['merchant','Merchants / services'],['reference','Reference']]);
 const completion=select('Completion status',[['all','All recorded states'],['open','Open or unrecorded'],['completed','Completed / acquired'],['unknown','Unknown / unrecorded'],['failed','Recorded failed']]);
 const storageMessage=make('p',null,'guide-search-message');storageMessage.setAttribute('role','status');
 const coverage=make('p','Search covers White Orchard, Velen and built Field Reference pages.','guide-search-coverage'),message=make('p',null,'guide-search-message'),results=make('section',null,'guide-search-results');message.setAttribute('role','status');results.setAttribute('aria-label','Search results');paper.append(header,form,filters,coverage,storageMessage,message,results);dialog.append(paper);document.body.append(dialog);
 const splash=make('section',null,'view scene guide-search-splash');
 splash.id='guide-search';splash.hidden=true;
 const splashTitle=make('h1','Search the guide');splashTitle.id='search-splash-title';
 splash.setAttribute('aria-labelledby',splashTitle.id);
 splash.append(splashTitle);(document.querySelector('#home')?.parentElement||document.body).append(splash);
 const onSplash=()=>location.hash.split('/')[0]==='#guide-search';
 function splashQuery(){return new URLSearchParams(location.hash.split('/').slice(1).join('/')).get('q')||'';}
 function showSplash(){
   splash.append(paper);header.hidden=true;
   const saved=history.state?.regionalSearch;
   input.value=saved?.query??splashQuery();region.value=saved?.region||'all';type.value=saved?.type||'all';completion.value=saved?.completion||'all';
   filters.open=!!saved?.filtersOpen;render();
   if(saved)requestAnimationFrame(()=>{results.scrollTop=saved.y;});
 }
 let origin=null,opened=false,session={query:'',region:'all',type:'all',completion:'all',y:0,filtersOpen:false,focusId:null},serial=0,generation=0;const returns=new Map();let returnButton=null;
 const viewport=()=>window.PhoenixViewport||window;
 const sizeDialog=()=>dialog.style.setProperty('--search-viewport-height',Math.round(window.visualViewport?.height||window.innerHeight)+'px');window.visualViewport?.addEventListener('resize',()=>{if(opened)sizeDialog();});
 const later=(frames,fn)=>{if(frames<=0)fn();else requestAnimationFrame(()=>later(frames-1,fn));};
 const sourceKey=()=>{let key=history.state?.searchSourceKey;if(!key){key='search-source-'+Date.now()+'-'+(++serial);history.replaceState({...history.state,searchSourceKey:key},'',location.href);}return key;};
 function captureOrigin(trigger,reopen){const view=document.querySelector('.view:not([hidden])');return {hash:location.hash||'#home',key:sourceKey(),y:viewport().scrollY,trigger,reopen,details:[...(view?.querySelectorAll('details')||[])].map(node=>({node,open:node.open})),rails:[...(view?.querySelectorAll('*')||[])].filter(node=>node.clientWidth>0&&(node.scrollWidth>node.clientWidth||node.scrollHeight>node.clientHeight)).map(node=>({node,x:node.scrollLeft,y:node.scrollTop})),diagram:view?.id==='gear-diagrams'?window.PhoenixDiagramRoutes?.captureCurrent():null};}
 function restoreSource(saved){if((location.hash||'#home')!==saved.hash)return;for(const {node,open}of saved.details)if(node.isConnected)node.open=open;for(const {node,x,y}of saved.rails)if(node.isConnected){node.scrollLeft=x;node.scrollTop=y;}if(saved.diagram)window.PhoenixDiagramRoutes?.restoreCurrent(saved.diagram);viewport().scrollTo(0,saved.y);}
 function remember(query,id){recents=model.remember(recents,{query,id});try{localStorage.setItem(historyKey,JSON.stringify(recents));storageMessage.textContent='';}catch{storageMessage.textContent='Search history could not be saved on this device. Search still works.';}}
 function currentSession(){return {query:input.value,region:region.value,type:type.value,completion:completion.value,y:results.scrollTop,filtersOpen:filters.open,focusId:session.focusId};}
 function result(row){const button=make('button',null,'guide-search-result');button.type='button';button.dataset.searchResult=row.id;const current=model.status(row,context);button.append(make('strong',row.title),make('span',[row.category,row.region,row.dlc,current.label].filter(Boolean).join(' · ')));button.onclick=()=>choose(row);return button;}
 function render(){const q=input.value.trim();results.replaceChildren();if(!q){message.textContent='';results.append(make('h3','Recent searches'));if(!recents.queries.length)results.append(make('p','Your searches will appear here.'));for(const query of recents.queries){const button=make('button',query,'guide-search-recent-query');button.type='button';button.onclick=()=>{input.value=query;results.scrollTop=0;render();input.focus({preventScroll:true});};results.append(button);}results.append(make('h3','Recently opened'));const entries=recents.entries.map(id=>byId.get(id)).filter(Boolean);if(!entries.length)results.append(make('p','Entries opened through Search will appear here.'));entries.forEach(row=>results.append(result(row)));return;}
  const matches=model.search(index,q,{region:region.value,type:type.value,completion:completion.value},context);message.textContent=matches.length+' result'+(matches.length===1?'':'s');if(!matches.length)results.append(make('p','No matching entries. Try fewer words or adjust the filters.','guide-search-empty'));for(const row of matches)results.append(result(row));
 }
 function open(trigger,options={}){if(onSplash()){input.focus();return;}if(opened){input.focus({preventScroll:true});return;}origin=options.origin||captureOrigin(trigger,options.reopen);session=options.session||{query:'',region:'all',type:'all',completion:'all',y:0,filtersOpen:false,focusId:null};input.value=session.query;region.value=session.region;type.value=session.type;completion.value=session.completion;filters.open=session.filtersOpen;render();opened=true;generation++;sizeDialog();viewport().lock?.();dialog.showModal();results.scrollTop=session.y;input.focus({preventScroll:true});if(options.session){const token=generation;later(2,()=>{if(!opened||token!==generation)return;results.scrollTop=session.y;[...results.querySelectorAll('[data-search-result]')].find(n=>n.dataset.searchResult===session.focusId)?.focus({preventScroll:true});});}}
 function close({reopenMenu=true,restore=true}={}){if(!opened)return;opened=false;generation++;session=currentSession();const saved=origin;dialog.close();viewport().unlock?.();if(restore&&saved)restoreSource(saved);if(reopenMenu&&saved?.reopen){const token=generation;later(1,()=>{if(!opened&&token===generation&&(location.hash||'#home')===saved.hash){saved.reopen();saved.trigger?.focus({preventScroll:true});}});}else if(restore&&saved?.trigger?.isConnected)saved.trigger.focus({preventScroll:true});}
 function choose(row){if(onSplash()){
  remember(input.value,row.id);
  history.replaceState({...history.state,regionalSearch:currentSession()},'',location.href);
  navigate(row.href);
  history.replaceState({...history.state,fromRegionalSearch:true},'',location.href);
  installReturn();return;
 }session=currentSession();session.focusId=row.id;const saved={id:'search-return-'+Date.now()+'-'+(++serial),origin,session,reopened:false,same:row.href===(location.hash||'#home')};remember(input.value,row.id);close({reopenMenu:false,restore:false});returns.set(saved.id,saved);navigate(row.href);history.replaceState({...history.state,searchReturn:saved.id},'',location.href);installReturn();}
 function resume(saved){if(!saved||opened)return;saved.reopened=true;const token=++generation;restoreSource(saved.origin);later(8,()=>{if(token!==generation||opened||(location.hash||'#home')!==saved.origin.hash)return;restoreSource(saved.origin);open(saved.origin.trigger,{origin:saved.origin,session:saved.session});});}
 function installReturn(){returnButton?.remove();returnButton=null;const saved=returns.get(history.state?.searchReturn);if(!saved&&!history.state?.fromRegionalSearch)return;if(saved)saved.reopened=false;const view=document.querySelector('.view:not([hidden])'),host=view?.querySelector('.reading-panel,.scene-inner,.main-console-inner')||view;if(!host)return;returnButton=make('button','Return to Search','guide-search-return');returnButton.type='button';returnButton.onclick=()=>saved?.same?resume(saved):history.back();host.prepend(returnButton);}
 closeButton.onclick=()=>close();dialog.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close();}});dialog.addEventListener('cancel',event=>{event.preventDefault();close();});dialog.addEventListener('close',()=>{if(opened)close();});dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=paper.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)close();});
 form.onsubmit=event=>{event.preventDefault();remember(input.value);if(onSplash())history.replaceState({...history.state,regionalSearch:currentSession()},'','#guide-search/'+new URLSearchParams({q:input.value.trim()}));render();results.scrollTop=0;};input.addEventListener('input',()=>{session.focusId=null;results.scrollTop=0;render();});for(const control of [region,type,completion])control.onchange=()=>{session.focusId=null;results.scrollTop=0;render();};
 for(const button of document.querySelectorAll('[data-open-search]'))button.addEventListener('click',()=>open(button));
 addEventListener('phoenix:route-rendered',()=>{if(opened&&(location.hash||'#home')!==origin.hash)close({reopenMenu:false,restore:false});if(onSplash())showSplash();else if(paper.parentNode===splash){dialog.append(paper);header.hidden=false;}installReturn();});
 addEventListener('popstate',()=>{const saved=[...returns.values()].reverse().find(item=>!item.reopened&&item.origin.key===history.state?.searchSourceKey&&(location.hash||'#home')===item.origin.hash);if(saved)resume(saved);});
 for(const name of ['phoenix:progress-committed','phoenix:progress-undone'])addEventListener(name,()=>{if(opened){const y=results.scrollTop;render();results.scrollTop=y;}});
 return {open,close,indexSize:index.length};
};
